import numpy as np

def problem(x: np.ndarray) -> float:
    """
    Synthetic benchmark function with a tunable fitness landscape.

    This function combines a quadratic bowl, a skewed exponential term,
    linear interactions, and radial basis functions to approximate the
    desired Exploratory Landscape Analysis (ELA) features.

    Formula:
    f(x) = quadratic_bowl(x) + skew_exp(x) + linear_interactions(x) + rbf(x)

    Args:
        x (np.ndarray): A 1D NumPy array of shape (N,) representing the input.

    Returns:
        float: The function value at the given input.
    """
    def quadratic_bowl(x):
        return np.sum(x**2)

    def skew_exp(x):
        return 0.5 * np.exp(0.5 * (x[0] -2)) #Adjusted to use x[0]

    def linear_interactions(x):
        return 0.1 * (x[0] * x[1] - x[2] * x[3]) #Adjusted to use indices

    def rbf(x):
      center1 = np.array([1, -1, 2, -2])
      center2 = np.array([-2, 2, -1, 1])
      return -0.2 * np.exp(-np.linalg.norm(x - center1)**2 / 2) - 0.2 * np.exp(-np.linalg.norm(x - center2)**2 / 2)

    return quadratic_bowl(x) + skew_exp(x) + linear_interactions(x) + rbf(x)
